/**
 * Real card-art resolver.
 * ------------------------------------------------------------------
 * Finished per-card art PNGs live in `public/cards/NNN.png`, indexed
 * 1..CARD_ART_COUNT (196×292 source, aspect-fit into the card art zone
 * with no alteration). The real art is tiled across the canonical
 * 992-serial deck so every rendered card shows real art; when the count
 * is 0 the caller falls back to the brand logo.
 *
 * Source art: Google Drive `Product & DEV / _MΛĐHATs Gambit DEV` —
 * NFTCards* batches (152 finished cards). Loaded in batches; CARD_ART_COUNT
 * is regenerated by `scripts/gen-card-art.mjs` as more art lands, so the
 * tiling widens (fewer repeats) automatically without touching callers.
 *
 * Rarity treatment (applied in nft-card.tsx, per founder plan): the rarest
 * (holographic) tiers render pure, unique art; lower tiers reuse tiled art
 * under a light faction-color wash so repeats read as faction variants, and
 * every card carries a gold-leaf faction emblem in the top border.
 */

// Auto-maintained by scripts/gen-card-art.mjs — do not edit by hand.
export const CARD_ART_COUNT = 13;

/** Resolve a card serial to its tiled real-art URL, or undefined when no
 *  art is present (caller then uses the brand-logo fallback). Deterministic
 *  per serial so a given card always shows the same art. */
export function cardArtUrl(serial: number): string | undefined {
  if (CARD_ART_COUNT <= 0) return undefined;
  const idx = (Math.abs(Math.trunc(serial)) % CARD_ART_COUNT) + 1; // 1..N
  return `/cards/${String(idx).padStart(3, "0")}.png`;
}
